32	 * User: fyodor
33	 * Date: 8/28/12
34	 */
35	public abstract class SingleTermRules<K> {
36	
37	  private ConcurrentHashMap<Object, Set<K>> myCachedRules = new ConcurrentHashMap<Object, Set<K>>();
38	
39	  public Set<K> lookupRules(SNode term) {
40	    final LanguageScope langScope = LanguageScope.getCurrent();
41	
42	    final SAbstractConcept concept = term.getConcept();
43	    final Object compoundKey = new Pair<Object, SAbstractConcept>(langScope, concept);
44	
45	    Set<K> cachedRules = myCachedRules.get(compoundKey);
46	    if (cachedRules != null) {
47	      return cachedRules;
48	    }
49	    return NodeReadAccessCasterInEditor.runReadTransparentAction(new Computable<Set<K>>() {
50	      @Override
51	      public Set<K> compute() {
52	        Set<K> computedRules = computeRules(concept, langScope);
53	        myCachedRules.put(compoundKey, computedRules);
54	
55	        return computedRules;
56	      }
57	    });
58	  }
59	
60	  public void purgeCache() {
61	    myCachedRules.clear();
62	  }
63	
64	  private Set<K> computeRules(SAbstractConcept concept, LanguageScope langScope) {
65	    THashSet<K> result = new THashSet<K>();
66	
67	    LinkedList<SAbstractConcept> queue = new LinkedList<SAbstractConcept>();
68	    queue.add(concept);
69	
70	    while (!queue.isEmpty()) {
71	      SAbstractConcept nextConceptFQName = queue.remove();
72	      boolean overriding = false;
73	      for (K applicableRule : allForConcept(nextConceptFQName, langScope)) {
74	        overriding |= isOverriding(applicableRule);
75	        result.add(applicableRule);
76	      }
77	      if (!overriding) {
78	        queue.addAll(getParents(nextConceptFQName));
79	      }
80	    }
81	
82	    return Collections.unmodifiableSet(result);
83	  }
84	
85	  abstract protected List<SAbstractConcept> getParents(SAbstractConcept nextConcept);
86	
87	  abstract protected Iterable<K> allForConcept(SAbstractConcept concept, LanguageScope scope);
88	
89	  abstract protected boolean isOverriding(K rule);
90	
91	}

